#!/usr/bin/env bash
#
# generate-nginx-override.sh - Generate nginx override with embedded persistent TLS certificate
#
# This script:
#   1. Fetches TLS certificate from Azure Key Vault
#   2. Generates a combined YAML file with Secret + Deployment
#   3. Outputs path to the generated file for use with idpbuilder -c nginx:
#
# Usage:
#   ./generate-nginx-override.sh [--output PATH]
#
# Output:
#   Default: /tmp/nginx-override-with-cert.yaml
#
# Environment:
#   AZURE_KEYVAULT_NAME - Key Vault name (default: keyvault-thcmfmoo5oeow)
#   STACKS_DIR - Path to stacks repository
#

set -euo pipefail

# Configuration
VAULT_NAME="${AZURE_KEYVAULT_NAME:-keyvault-thcmfmoo5oeow}"
OUTPUT_FILE="${1:-/tmp/nginx-override-with-cert.yaml}"
STACKS_DIR="${STACKS_DIR:-$(cd "$(dirname "${BASH_SOURCE[0]}")/../../.." && pwd)}"
NGINX_TEMPLATE="$STACKS_DIR/deployment/overrides/nginx-hostnetwork-no-hostport.yaml"

# Colors
GREEN='\033[0;32m'
YELLOW='\033[1;33m'
RED='\033[0;31m'
BLUE='\033[0;34m'
NC='\033[0m'

log_info() { echo -e "${BLUE}i${NC} $*" >&2; }
log_success() { echo -e "${GREEN}✓${NC} $*" >&2; }
log_warning() { echo -e "${YELLOW}⚠${NC} $*" >&2; }
log_error() { echo -e "${RED}✖${NC} $*" >&2; }

# Parse arguments
while [[ $# -gt 0 ]]; do
    case "$1" in
        --output)
            OUTPUT_FILE="$2"
            shift 2
            ;;
        --help|-h)
            echo "Usage: $0 [--output PATH]"
            echo ""
            echo "Generates nginx override YAML with embedded TLS certificate from Azure Key Vault."
            echo ""
            echo "Options:"
            echo "  --output PATH    Output file path (default: /tmp/nginx-override-with-cert.yaml)"
            exit 0
            ;;
        *)
            # If not a flag, assume it's the output path
            if [[ ! "$1" =~ ^- ]]; then
                OUTPUT_FILE="$1"
            fi
            shift
            ;;
    esac
done

# Check prerequisites
command -v az &>/dev/null || { log_error "Azure CLI (az) not found"; exit 1; }

# Check if persistent secrets exist in Key Vault
log_info "Checking for persistent TLS certificate in Azure Key Vault..."

if ! az keyvault secret show --vault-name "$VAULT_NAME" --name "IDPBUILDER-TLS-CRT" &>/dev/null; then
    log_warning "Persistent TLS certificate not found in Key Vault"
    log_warning "Run setup-persistent-certs.sh first to generate and upload certificates"
    log_info "Falling back to standard nginx override without embedded certificate"

    # Fall back to just copying the template (idpbuilder will generate its own cert)
    if [ -f "$NGINX_TEMPLATE" ]; then
        cp "$NGINX_TEMPLATE" "$OUTPUT_FILE"
        log_info "Using standard nginx template: $OUTPUT_FILE"
        echo "$OUTPUT_FILE"
        exit 0
    else
        log_error "Nginx template not found: $NGINX_TEMPLATE"
        exit 1
    fi
fi

# Fetch certificates from Azure Key Vault
log_info "Fetching TLS certificate from Azure Key Vault..."

TLS_CRT=$(az keyvault secret show --vault-name "$VAULT_NAME" --name "IDPBUILDER-TLS-CRT" --query value -o tsv)
TLS_KEY=$(az keyvault secret show --vault-name "$VAULT_NAME" --name "IDPBUILDER-TLS-KEY" --query value -o tsv)

if [ -z "$TLS_CRT" ] || [ -z "$TLS_KEY" ]; then
    log_error "Failed to fetch TLS certificate or key from Key Vault"
    exit 1
fi

log_success "TLS certificate fetched from Key Vault"

# Generate combined override file
log_info "Generating nginx override with embedded certificate..."

cat > "$OUTPUT_FILE" <<'YAML_HEADER'
# Auto-generated nginx override with persistent TLS certificate
# Generated by: generate-nginx-override.sh
# Do not edit - regenerate by running the script again
---
apiVersion: v1
kind: Secret
metadata:
  name: persistent-tls-cert
  namespace: ingress-nginx
  labels:
    app.kubernetes.io/name: persistent-tls-cert
    app.kubernetes.io/part-of: idpbuilder
type: kubernetes.io/tls
data:
YAML_HEADER

# Add certificate data (already base64 encoded from AKV)
echo "  tls.crt: ${TLS_CRT}" >> "$OUTPUT_FILE"
echo "  tls.key: ${TLS_KEY}" >> "$OUTPUT_FILE"

# Add the deployment manifest
cat >> "$OUTPUT_FILE" <<'YAML_DEPLOYMENT'
---
apiVersion: apps/v1
kind: Deployment
metadata:
  labels:
    app.kubernetes.io/component: controller
    app.kubernetes.io/instance: ingress-nginx
    app.kubernetes.io/name: ingress-nginx
    app.kubernetes.io/part-of: ingress-nginx
    app.kubernetes.io/version: 1.13.0
  name: ingress-nginx-controller
  namespace: ingress-nginx
spec:
  minReadySeconds: 0
  revisionHistoryLimit: 10
  selector:
    matchLabels:
      app.kubernetes.io/component: controller
      app.kubernetes.io/instance: ingress-nginx
      app.kubernetes.io/name: ingress-nginx
  strategy:
    rollingUpdate:
      maxUnavailable: 1
    type: RollingUpdate
  template:
    metadata:
      labels:
        app.kubernetes.io/component: controller
        app.kubernetes.io/instance: ingress-nginx
        app.kubernetes.io/name: ingress-nginx
        app.kubernetes.io/part-of: ingress-nginx
        app.kubernetes.io/version: 1.8.1
    spec:
      # KIND + Docker can accumulate stale CNI hostPort DNAT rules after reboot,
      # which breaks access to the cluster ingress. Using hostNetwork avoids the
      # CNI hostPort/portmap rules entirely.
      hostNetwork: true
      dnsPolicy: ClusterFirstWithHostNet
      automountServiceAccountToken: true
      containers:
        - args:
            - /nginx-ingress-controller
            - --election-id=ingress-nginx-leader
            - --controller-class=k8s.io/ingress-nginx
            - --ingress-class=nginx
            - --configmap=$(POD_NAMESPACE)/ingress-nginx-controller
            - --validating-webhook=:8443
            - --validating-webhook-certificate=/usr/local/certificates/cert
            - --validating-webhook-key=/usr/local/certificates/key
            - --watch-ingress-without-class=true
            - --publish-status-address=localhost
            - --enable-ssl-passthrough
            - --default-ssl-certificate=ingress-nginx/persistent-tls-cert
          env:
            - name: POD_NAME
              valueFrom:
                fieldRef:
                  fieldPath: metadata.name
            - name: POD_NAMESPACE
              valueFrom:
                fieldRef:
                  fieldPath: metadata.namespace
            - name: LD_PRELOAD
              value: /usr/local/lib/libmimalloc.so
          image: registry.k8s.io/ingress-nginx/controller:v1.13.0@sha256:dc75a7baec7a3b827a5d7ab0acd10ab507904c7dad692365b3e3b596eca1afd2
          imagePullPolicy: IfNotPresent
          lifecycle:
            preStop:
              exec:
                command:
                  - /wait-shutdown
          livenessProbe:
            failureThreshold: 5
            httpGet:
              path: /healthz
              port: 10254
              scheme: HTTP
            initialDelaySeconds: 10
            periodSeconds: 10
            successThreshold: 1
            timeoutSeconds: 1
          name: controller
          ports:
            - containerPort: 80
              name: http
              protocol: TCP
            - containerPort: 443
              name: https
              protocol: TCP
            - containerPort: 8443
              name: webhook
              protocol: TCP
          readinessProbe:
            failureThreshold: 3
            httpGet:
              path: /healthz
              port: 10254
              scheme: HTTP
            initialDelaySeconds: 10
            periodSeconds: 10
            successThreshold: 1
            timeoutSeconds: 1
          resources:
            requests:
              cpu: 100m
              memory: 90Mi
          securityContext:
            allowPrivilegeEscalation: false
            capabilities:
              add:
                - NET_BIND_SERVICE
              drop:
                - ALL
            readOnlyRootFilesystem: false
            runAsGroup: 82
            runAsNonRoot: true
            runAsUser: 101
            seccompProfile:
              type: RuntimeDefault
          volumeMounts:
            - mountPath: /usr/local/certificates/
              name: webhook-cert
              readOnly: true
      nodeSelector:
        kubernetes.io/os: linux
      serviceAccountName: ingress-nginx
      terminationGracePeriodSeconds: 0
      tolerations:
        - effect: NoSchedule
          key: node-role.kubernetes.io/master
          operator: Equal
        - effect: NoSchedule
          key: node-role.kubernetes.io/control-plane
          operator: Equal
      volumes:
        - name: webhook-cert
          secret:
            secretName: ingress-nginx-admission
YAML_DEPLOYMENT

log_success "Generated nginx override: $OUTPUT_FILE"

# Also generate ArgoCD override with CA trust ConfigMap AND performance tuning
# This allows ArgoCD repo-server to connect to Gitea over HTTPS with our custom cert
# Performance tuning enables faster sync for 128+ applications
ARGOCD_OVERRIDE_FILE="/tmp/argocd-override-with-ca.yaml"

log_info "Generating ArgoCD override with CA trust and performance tuning..."

# Fetch CA certificate
CA_CRT=$(az keyvault secret show --vault-name "$VAULT_NAME" --name "IDPBUILDER-CA-CRT" --query value -o tsv | base64 -d)

if [ -n "$CA_CRT" ]; then
    cat > "$ARGOCD_OVERRIDE_FILE" <<EOF
# Auto-generated ArgoCD override with persistent CA trust and performance tuning
# Generated by: generate-nginx-override.sh
# Do not edit - regenerate by running the script again
---
# Performance tuning for ArgoCD controller
# Optimized for syncing 128+ applications quickly
apiVersion: v1
kind: ConfigMap
metadata:
  name: argocd-cmd-params-cm
  namespace: argocd
  labels:
    app.kubernetes.io/name: argocd-cmd-params-cm
    app.kubernetes.io/part-of: argocd
data:
  # Status processors: concurrent status update goroutines (default: 20)
  controller.status.processors: "50"
  # Operation processors: concurrent sync operations (default: 10)
  controller.operation.processors: "25"
  # Kubectl parallelism: concurrent kubectl commands (default: 20)
  controller.kubectl.parallelism.limit: "30"
  # Use server-side diff for more accurate comparison
  controller.diff.server.side: "true"
  # Repo server parallelism: concurrent manifest generation
  reposerver.parallelism.limit: "50"
---
# CA trust for Gitea HTTPS connections
apiVersion: v1
kind: ConfigMap
metadata:
  name: argocd-tls-certs-cm
  namespace: argocd
  labels:
    app.kubernetes.io/name: argocd-tls-certs-cm
    app.kubernetes.io/part-of: argocd
data:
  gitea.cnoe.localtest.me: |
$(echo "$CA_CRT" | sed 's/^/    /')
EOF
    log_success "Generated ArgoCD override: $ARGOCD_OVERRIDE_FILE (CA trust + performance tuning)"
else
    log_warning "Could not fetch CA certificate for ArgoCD trust"
fi

# Output the file path for use in scripts
echo "$OUTPUT_FILE"
